param(
    [string]$ProjectRoot = ""
)

# Generates the quantum tier block assets: textures, blockstates, models, loot tables and recipes.
# Textures are recoloured copies of the nano tier textures (teal #6AAE9D metallic style).
# The progress arrows are shared with the nano tier and are generated by generate_nano_assets.ps1.

$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.Drawing

if ([string]::IsNullOrWhiteSpace($ProjectRoot)) {
    $ProjectRoot = (Resolve-Path (Join-Path $PSScriptRoot "..")).Path
}

$assets = Join-Path $ProjectRoot "src\main\resources\assets\ascension_ic2"
$data = Join-Path $ProjectRoot "src\main\resources\data\ascension_ic2"
$nanoTextureDir = Join-Path $assets "textures\block\nano"
$quantumTextureDir = Join-Path $assets "textures\block\quantum"
$blockstateDir = Join-Path $assets "blockstates"
$blockModelDir = Join-Path $assets "models\block"
$itemModelDir = Join-Path $assets "models\item"
$lootDir = Join-Path $data "loot_table\blocks"
$recipeDir = Join-Path $data "recipe"
$tagBlockDir = Join-Path $ProjectRoot "src\main\resources\data\minecraft\tags\block"
$tagMineableDir = Join-Path $tagBlockDir "mineable"

foreach ($dir in @($quantumTextureDir, $blockstateDir, $blockModelDir, $itemModelDir, $lootDir, $recipeDir, $tagMineableDir)) {
    New-Item -ItemType Directory -Path $dir -Force | Out-Null
}

$machines = @(
    @{ Id = "quantum_macerator"; Nano = "nano_macerator"; Base = "macerator" },
    @{ Id = "quantum_electric_furnace"; Nano = "nano_electric_furnace"; Base = "electric_furnace" },
    @{ Id = "quantum_compressor"; Nano = "nano_compressor"; Base = "compressor" },
    @{ Id = "quantum_extractor"; Nano = "nano_extractor"; Base = "extractor" },
    @{ Id = "quantum_recycler"; Nano = "nano_recycler"; Base = "recycler" }
)

function Write-JsonFile([string]$Path, $Value) {
    $json = $Value | ConvertTo-Json -Depth 12
    $utf8 = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($Path, $json, $utf8)
}

# Recolour a nano texture to the quantum palette: keep the shading, shift it to teal (#6AAE9D).
function Convert-ToQuantum([string]$InPath, [string]$OutPath) {
    $src = [System.Drawing.Bitmap]::FromFile($InPath)
    try {
        $dst = New-Object System.Drawing.Bitmap($src.Width, $src.Height, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
        $baseR = 106
        $baseG = 174
        $baseB = 157
        for ($y = 0; $y -lt $src.Height; $y++) {
            for ($x = 0; $x -lt $src.Width; $x++) {
                $c = $src.GetPixel($x, $y)
                if ($c.A -eq 0) {
                    $dst.SetPixel($x, $y, $c)
                    continue
                }
                $lum = 0.299 * $c.R + 0.587 * $c.G + 0.114 * $c.B
                $f = [Math]::Min(1.5, [Math]::Max(0.28, $lum / 128.0))
                $r = [Math]::Min(255, [Math]::Max(0, [int]($baseR * $f)))
                $g = [Math]::Min(255, [Math]::Max(0, [int]($baseG * $f)))
                $b = [Math]::Min(255, [Math]::Max(0, [int]($baseB * $f)))
                $dst.SetPixel($x, $y, [System.Drawing.Color]::FromArgb($c.A, $r, $g, $b))
            }
        }
        $dst.Save($OutPath, [System.Drawing.Imaging.ImageFormat]::Png)
        $dst.Dispose()
    }
    finally {
        $src.Dispose()
    }
}

foreach ($machine in $machines) {
    $id = $machine.Id
    $nano = $machine.Nano

    foreach ($part in @("front", "side", "top", "bottom")) {
        $inFile = Join-Path $nanoTextureDir "${nano}_$part.png"
        if (-not (Test-Path $inFile)) {
            throw "Missing nano texture: $inFile (run generate_nano_assets.ps1 first)"
        }
        Convert-ToQuantum $inFile (Join-Path $quantumTextureDir "${id}_$part.png")
    }

    Write-JsonFile (Join-Path $blockstateDir "$id.json") @{
        variants = @{
            "facing=north" = @{ model = "ascension_ic2:block/$id" }
            "facing=east" = @{ model = "ascension_ic2:block/$id"; y = 90 }
            "facing=south" = @{ model = "ascension_ic2:block/$id"; y = 180 }
            "facing=west" = @{ model = "ascension_ic2:block/$id"; y = 270 }
        }
    }

    Write-JsonFile (Join-Path $blockModelDir "$id.json") @{
        parent = "minecraft:block/cube"
        textures = @{
            particle = "ascension_ic2:block/quantum/${id}_side"
            down = "ascension_ic2:block/quantum/${id}_bottom"
            up = "ascension_ic2:block/quantum/${id}_top"
            north = "ascension_ic2:block/quantum/${id}_front"
            south = "ascension_ic2:block/quantum/${id}_side"
            west = "ascension_ic2:block/quantum/${id}_side"
            east = "ascension_ic2:block/quantum/${id}_side"
        }
    }

    Write-JsonFile (Join-Path $itemModelDir "$id.json") @{
        parent = "ascension_ic2:block/$id"
    }

    Write-JsonFile (Join-Path $lootDir "$id.json") @{
        type = "minecraft:block"
        pools = @(
            @{
                rolls = 1
                bonus_rolls = 0
                entries = @(
                    @{ type = "minecraft:item"; name = "ascension_ic2:${id}" }
                )
                conditions = @(
                    @{ condition = "minecraft:survives_explosion" }
                )
            }
        )
        random_sequence = "ascension_ic2:blocks/$id"
    }

    Write-JsonFile (Join-Path $recipeDir "$id.json") @{
        type = "minecraft:crafting_shapeless"
        category = "misc"
        ingredients = @(
            @{ item = "ascension_ic2:quantum_base" }
            @{ item = "ascension_ic2:$nano" }
            @{ item = "ascension_ic2:$nano" }
            @{ item = "ascension_ic2:quantum_circuit" }
            @{ item = "ascension_ic2:quantum_circuit" }
        )
        result = @{
            id = "ascension_ic2:${id}"
            count = 1
        }
    }
}

# Both tiers share the block tags; the list is identical to the one written by the nano script.
$allIds = @()
foreach ($machine in $machines) {
    $base = $machine.Base
    $allIds += "ascension_ic2:nano_$base"
    $allIds += "ascension_ic2:quantum_$base"
}
Write-JsonFile (Join-Path $tagMineableDir "pickaxe.json") @{
    replace = $false
    values = $allIds
}
Write-JsonFile (Join-Path $tagBlockDir "needs_iron_tool.json") @{
    replace = $false
    values = $allIds
}

Write-Output "Generated quantum assets for $($machines.Count) machines."
